// Extract URL and triage message
const msg = $input.first().json.message || {};
const text = (msg.text || '').trim();
const urlRegex = /(https?:\/\/[^\s]+)/gi;
const match = text.match(urlRegex);
const extractedUrl = match ? match[0].replace(/[)\]>,."']+$/, '') : null;

const isQueueCmd = text.startsWith('/queue') || text.startsWith('/q');
const isDoneCmd = text.startsWith('/qdone') || text.startsWith('/done');
const isCurateCmd = text.startsWith('/curate');

let actionType = 'curate';
if (isQueueCmd) actionType = 'show_queue';
else if (isDoneCmd) actionType = 'mark_done';

return [{
  json: {
    chatId: msg.chat?.id,
    text,
    url: extractedUrl,
    hasUrl: Boolean(extractedUrl),
    actionType,
    rawMessage: msg,
    cmdArg: text.split(' ').slice(1).join(' ').trim()
  }
}];

const html = $input.first().json.data || $input.first().json.body || '';
const parent = $('Parse URL & Commands').first().json;

// Extract title & OpenGraph description
const titleMatch = html.match(/<meta[^>]*property=["']og:title["'][^>]*content=["']([^"']+)["']/i) ||
                   html.match(/<title[^>]*>([^<]+)<\/title>/i);
const descMatch = html.match(/<meta[^>]*property=["']og:description["'][^>]*content=["']([^"']+)["']/i) ||
                  html.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']+)["']/i);

const cleanTitle = titleMatch ? titleMatch[1].trim() : (parent.url || 'Curation Item');
const cleanDesc = descMatch ? descMatch[1].trim() : '';

return [{
  json: {
    ...parent,
    pageTitle: cleanTitle,
    pageDescription: cleanDesc,
    htmlSnippet: html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').slice(0, 1200)
  }
}];

