let raw = $input.first().json.message?.content || $input.first().json.response || '';
const jsonMatch = raw.match(/\{[\s\S]*\}/);
let analysis = {};
try {
  analysis = JSON.parse(jsonMatch ? jsonMatch[0] : raw);
} catch (e) {
  analysis = {
    title: 'New Curation Item',
    category: 'idea',
    target_project: 'general',
    priority: 'medium',
    takeaways: ['Review in Antigravity session'],
    why_it_matters: 'Relevant to ongoing development',
    antigravity_action: 'Inspect and evaluate in workspace'
  };
}

const parent = $('Clean Scraped Metadata').first().json;
const shortId = 'Q-' + Math.floor(100 + Math.random() * 900);

const cardText = `📥 *Queued for Antigravity* \`[#${shortId}]\`\n\n📌 *${analysis.title}*\n📂 *Target:* ${analysis.category.toUpperCase()} → \`${analysis.target_project}\`\n⚡ *Priority:* ${analysis.priority.toUpperCase()}\n${parent.url ? `🔗 *Link:* ${parent.url}\n` : ''}\n💡 *Key Takeaways:*\n${(analysis.takeaways || []).map(t => '• ' + t).join('\n')}\n\n🎯 *Why this matters:*\n${analysis.why_it_matters}\n\n🛠 *Antigravity Action:*\n\`${analysis.antigravity_action}\`\n\n_Synced to Obsidian vault & ready for desktop Antigravity session!_`;

return [{
  json: {
    ...parent,
    shortId,
    analysis,
    cardText
  }
}];
